import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { describe, expect, it } from "vitest";
import { framedCeilingAssemblyR, framedWallAssemblyR } from "../../src/methods/assembly-r.js";
import { WOOD_FRAMING_SETS } from "../../src/methods/coefficients.js";

interface OracleCase {
  kind: "wall" | "ceiling";
  stud_nominal_in: number;
  framing_factor: number;
  cavity_r: number;
  continuous_r: number;
  siding: string;
  osb_in: number;
  assembly_r: number;
  oracle_picker_cavity_r: number;
}

// Generated by tools/hpxml-oracle/assembly-r-oracle.rb under the pinned OpenStudio 3.11.0.
const oracle = JSON.parse(readFileSync(resolve(import.meta.dirname, "../../fixtures/oracle/assembly-r.json"), "utf8")) as { cases: OracleCase[] };

describe("MJ8.construction.assembly_r vs the oracle's Construction#assembly_rvalue", () => {
  it("has the full case matrix (30 walls, 9 ceilings)", () => {
    expect(oracle.cases.filter((c) => c.kind === "wall").length).toBe(30);
    expect(oracle.cases.filter((c) => c.kind === "ceiling").length).toBe(9);
  });

  for (const c of oracle.cases) {
    const label = `${c.kind} 2x${c.stud_nominal_in} ff ${c.framing_factor} cavity R-${c.cavity_r} continuous R-${c.continuous_r} ${c.siding}`;
    it(`${label} -> R-${c.assembly_r.toFixed(3)}`, () => {
      const r =
        c.kind === "wall"
          ? framedWallAssemblyR({
              studNominalIn: c.stud_nominal_in,
              framingFactor: c.framing_factor,
              cavityR: c.cavity_r,
              continuousR: c.continuous_r,
              siding: c.siding,
              interiorFinish: "gypsum board",
              sheathingThicknessIn: c.osb_in,
            })
          : framedCeilingAssemblyR({
              joistNominalIn: c.stud_nominal_in,
              framingFactor: c.framing_factor,
              cavityR: c.cavity_r,
              aboveJoistR: c.continuous_r,
              interiorFinish: "gypsum board",
            });
      expect(Math.abs(r.assemblyR - c.assembly_r)).toBeLessThan(1e-9);
      // The oracle's own inverse recovered the input cavity R from this assembly R (empty bays recover the air-gap R).
      expect(c.oracle_picker_cavity_r).toBeCloseTo(c.cavity_r > 0 ? c.cavity_r : c.kind === "wall" ? 1.0 : 0.0, 6);
    });
  }
});

describe("MJ8.construction.assembly_r behaviour", () => {
  it("the reference sets match the oracle's construction sets", () => {
    expect(WOOD_FRAMING_SETS.wall2x4At16).toEqual({ studNominalIn: 4, framingFactor: 0.23 });
    expect(WOOD_FRAMING_SETS.ceiling2x6At24).toEqual({ studNominalIn: 6, framingFactor: 0.1 });
  });

  it("the uninsulated 2x4 brick ranch wall is R-4.15, close to the R-4.0 placeholder in the ranch fixture", () => {
    const r = framedWallAssemblyR({ studNominalIn: 4, framingFactor: 0.23, cavityR: 0, continuousR: 0, siding: "brick veneer", interiorFinish: "gypsum board", sheathingThicknessIn: 0.5 });
    expect(r.assemblyR).toBeCloseTo(4.147, 3);
  });

  it("refuses unsupported sizes, sidings and out-of-range inputs", () => {
    const base = { studNominalIn: 4, framingFactor: 0.23, cavityR: 13, continuousR: 0, siding: "brick veneer", interiorFinish: "gypsum board" as const, sheathingThicknessIn: 0.5 };
    expect(() => framedWallAssemblyR({ ...base, studNominalIn: 5 })).toThrow(/2x5/);
    expect(() => framedWallAssemblyR({ ...base, siding: "log" })).toThrow(/siding/);
    expect(() => framedWallAssemblyR({ ...base, framingFactor: 1 })).toThrow(/framing factor/);
    expect(() => framedWallAssemblyR({ ...base, cavityR: -1 })).toThrow(/non-negative/);
  });
});
